			select {
			case result = <-slot.ch:
				timer.Stop()
			case <-timer.C:
				// Timeout: close done to signal the loading goroutine
				// to abort, delete the loading slot, and fall through
				// to a direct inner call (issue #800).
				close(slot.done)
				c.mu.Lock()
				delete(c.loading, key)
				c.mu.Unlock()
				return c.inner.Embed(ctx, text)
			case <-ctx.Done():
				timer.Stop()
				close(slot.done)
				c.mu.Lock()
				delete(c.loading, key)
				c.mu.Unlock()
				return nil, ctx.Err()
			}
		} else {
